def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != background:
                points.setdefault(v, []).append((r, c))
    out = [row[:] for row in grid]
    for color, pts in points.items():
        cr = sum(r for r, c in pts) / len(pts)
        cc = sum(c for r, c in pts) / len(pts)
        # Extend the diagonal stroke from its outward-most endpoint.
        for r, c in pts:
            for dr, dc in ((1, -1), (1, 1)):
                nr, nc = r + dr, c + dc
                if (nr, nc) not in pts:
                    continue
                # Of the pair, continue from the endpoint farther from the color's center.
                d1 = (r-cr)**2 + (c-cc)**2
                d2 = (nr-cr)**2 + (nc-cc)**2
                if d1 >= d2:
                    sr, sc, er, ec = r, c, r-dr, c-dc
